==== e683286b
commit e683286bb412e0e11db2b7329c7836dcf5c5c38c
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Sat Mar 18 19:53:00 2023 +0100

    Add use of stdin to fuzzer_tool_flac, and redirect stdout
---
 oss-fuzz/tool_flac.c | 37 ++++++++++++++++++++++++++++++++-----
 1 file changed, 32 insertions(+), 5 deletions(-)

diff --git a/oss-fuzz/tool_flac.c b/oss-fuzz/tool_flac.c
index 3f6b2b21..23bab345 100644
--- a/oss-fuzz/tool_flac.c
+++ b/oss-fuzz/tool_flac.c
@@ -46,8 +46,11 @@ int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
 	char * argv[67];
 	char exename[] = "flac";
 	char filename[] = "/tmp/fuzzXXXXXX";
-	int numarg = 0, maxarg, pad;
+	int numarg = 0, maxarg;
 	int file_to_fuzz;
+	int tmp_stdout, tmp_stdin;
+	fpos_t pos_stdout;
+	bool use_stdin = false;

 	/* reset global vars */
 	flac__utils_verbosity_ = 0;
@@ -59,7 +62,7 @@ int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
 		return 0;

 	maxarg = data[0] & 63;
-	pad = data[0] & 64;
+	use_stdin = data[0] & 64;
 	size_left--;

 	argv[0] = exename;
@@ -76,14 +79,38 @@ int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
 	if (file_to_fuzz < 0)
 		abort();
 	write(file_to_fuzz,data+(size-size_left),size_left);
-	if(pad)
-		write(file_to_fuzz,"\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00",12);
 	close(file_to_fuzz);

-	argv[numarg++] = filename;
+	/* redirect stdout */
+	fflush(stdout);
+	fgetpos(stdout,&pos_stdout);
+	tmp_stdout = dup(fileno(stdout));
+	freopen("/dev/null","w",stdout);
+
+	/* redirect stdin */
+	tmp_stdin = dup(fileno(stdin));
+
+	if(use_stdin)
+		freopen(filename,"r",stdin);
+	else {
+		freopen("/dev/null","r",stdin);
+		argv[numarg++] = filename;
+	}

 	main_to_fuzz(numarg,argv);

+	/* restore stdout */
+	fflush(stdout);
+	dup2(tmp_stdout, fileno(stdout));
+	close(tmp_stdout);
+	clearerr(stdout);
+	fsetpos(stdout,&pos_stdout);
+
+	/* restore stdin */
+	dup2(tmp_stdin, fileno(stdin));
+	close(tmp_stdin);
+	clearerr(stdin);
+
 	unlink(filename);

 	return 0;


